import{_ as d,a0 as p,w as e,s as l,I as i,x as o,a1 as r,A as s,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 Linux 圖形棧上運行 Android | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 圖形棧上運行 Android | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 圖形棧上運行 Android | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 圖形棧上運行 Android | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171020 Running Android on Top of a Linux Graphics Stack","title":"在 Linux 圖形棧上運行 Android","tag":"201711","desc":""},"relativePath":"201711/20171020 Running Android on Top of a Linux Graphics Stack.md","filePath":"[post].md"}'),a={name:"201711/20171020 Running Android on Top of a Linux Graphics Stack.md"};function x(A,n,L,g,m,f){const t=p("Link");return e(),l("div",null,[n[18]||(n[18]=i("h1",{id:"在-linux-圖形棧上運行-android",tabindex:"-1"},[o("在 Linux 圖形棧上運行 Android "),i("a",{class:"header-anchor",href:"#在-linux-圖形棧上運行-android","aria-label":"Permalink to “在 Linux 圖形棧上運行 Android”"},"​")],-1)),n[19]||(n[19]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/linux-graphics-stack.jpg?itok=qGxdvJA7",alt:"Linux graphics",title:"Linux graphics"})],-1)),i("blockquote",null,[i("p",null,[n[1]||(n[1]=o("根據 Collabora 的 Linux 圖形棧貢獻者和軟件工程師 Robert Foss 的説法，你現在可以在常規的 Linux 圖形處理平台上運行 Android，這是非常強大的功能。瞭解更多關於他在歐洲嵌入式 Linux 會議上的演講。",-1)),r(t,{href:"https://www.linux.com/licenses/category/creative-commons-zero"},{default:s(()=>[...n[0]||(n[0]=[o("Creative Commons Zero",-1)])]),_:1}),n[2]||(n[2]=o(" Pixabay",-1))])]),i("p",null,[n[4]||(n[4]=o("你現在可以在常規的 Linux 圖形棧之上運行 Android。以前並不能這樣，根據 Collabora 的 Linux 圖形棧貢獻者和軟件工程師 Robert Foss 的説法，這是非常強大的功能。在即將舉行的",-1)),r(t,{href:"http://events.linuxfoundation.org/events/embedded-linux-conference-europe"},{default:s(()=>[...n[3]||(n[3]=[o("歐洲 Linux 嵌入式會議",-1)])]),_:1}),n[5]||(n[5]=o("的講話中，Foss 將會介紹這一領域的最新進展，並討論這些變化如何讓你可以利用內核中的新功能和改進。",-1))]),n[20]||(n[20]=u("<p>在本文中，Foss 解釋了更多內容，並提供了他的演講的預覽。</p><p><strong>Linux.com：你能告訴我們一些你談論的圖形棧嗎？</strong></p><p><strong>Foss：</strong> 傳統的 Linux 圖形系統（如 X11）大都沒有使用<ruby>平面圖形<rt>plane</rt></ruby>。但像 Android 和 Wayland 這樣的現代圖形系統可以充分利用它。</p><p>Android 在 HWComposer 中最成功實現了平面支持，其圖形棧與通常的 Linux 桌面圖形棧有所不同。在桌面上，典型的合成器只是使用 GPU 進行所有的合成，因為這是桌面上唯一有的東西。</p><p>大多數嵌入式和移動芯片都有為 Android 設計的專門的 2D 合成硬件。這是通過將顯示的內容分成不同的圖層，然後智能地將圖層送到經過優化處理圖層的硬件。這就可以釋放 GPU 來處理你真正關心的事情，同時它讓硬件更有效率地做最好一件事。</p><p><strong>Linux.com：當你説到 Android 時，你的意思是 Android 開源項目 （AOSP） 麼？</strong></p><p><strong>Foss：</strong> Android 開源項目（AOSP）是許多 Android 產品建立的基礎，AOSP 和 Android 之間沒有什麼區別。</p><p>具體來説，我的工作已經在 AOSP 上完成，但沒有什麼可以阻止將此項工作加入到已經發貨的 Android 產品中。</p><p>區別更多在於授權和滿足 Google 對 Android 產品的要求，而不是代碼。</p><p><strong>Linux.com： 誰想要運行它，為什麼？有什麼好處？</strong></p><p><strong>Foss：</strong> AOSP 為你提供了大量免費的東西，例如針對可用性、低功耗和多樣化硬件進行優化的軟件棧。它比任何一家公司自行開發的更精緻、更靈活, 而不需要投入大量資源。</p><p>作為製造商，它還為你提供了一個能夠立即為你的平台開發的大量開發人員。</p><p><strong>Linux.com：有什麼實際使用情況？</strong></p><p>** Foss：** 新的部分是在常規 Linux 圖形棧上運行 Android 的能力。可以在主線/上游內核和驅動來做到這一點，讓你可以利用內核中的新功能和改進，而不僅僅依賴於來自於你的供應商的大量分支的 BSP。</p><p>對於任何有合理標準的 Linux 支持的 GPU，你現在可以在上面運行 Android。以前並不能這樣。而且這樣做是非常強大的。</p><p>同樣重要的是，它鼓勵 GPU 設計者與上游的驅動一起工作。現在他們有一個簡單的方法來提供適用於 Android 和 Linux 的驅動程序，而無需額外的努力。他們的成本將會降低，維護上游 GPU 驅動變得更有吸引力。</p><p>例如，我們希望看到主線內核支持高通 SOC，我們希望成為實現這一目標的一部分。</p><p>總而言之，這將有助於硬件生態系統獲得更好的軟件支持，軟件生態系統有更多的硬件配合。</p><ul><li>它改善了 SBC/開發板製造商的經濟性：它們可以提供一個經過良好測試的棧，既可以在兩者之間工作，而不必提供 “Linux 棧” 和 Android 棧。</li><li>它簡化了驅動程序開發人員的工作，因為只有一個優化和支持目標。</li><li>它支持 Android 社區，因為在主線內核上運行的 Android 可以讓他們分享上游的改進。</li><li>這有助於上游，因為我們獲得了一個產品級質量的棧，這些棧已經在硬件設計師的幫助下進行了測試和開發。</li></ul><p>以前，Mesa 被視為二等棧，但現在它是最新的（完全符合 Vulkan 1.0、OpenGL 4.6、OpenGL ES 3.2）另外還有性能和產品質量。</p><p>這意味着驅動開發人員可以參與 Mesa，相信他們正在分享他人的辛勤工作，並且還有一個很好的基礎。</p><hr>",22)),i("p",null,[n[7]||(n[7]=o("via: ",-1)),r(t,{href:"https://www.linux.com/blog/event/elce/2017/10/running-android-top-linux-graphics-stack"},{default:s(()=>[...n[6]||(n[6]=[o("https://www.linux.com/blog/event/elce/2017/10/running-android-top-linux-graphics-stack",-1)])]),_:1})]),i("p",null,[n[10]||(n[10]=o("作者：",-1)),r(t,{href:"https://www.linux.com/users/arnieswap"},{default:s(()=>[...n[8]||(n[8]=[o("SWAPNIL BHARTIYA",-1)])]),_:1}),n[11]||(n[11]=o(" 譯者：",-1)),r(t,{href:"https://github.com/geekpi"}),n[12]||(n[12]=o(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:s(()=>[...n[9]||(n[9]=[o("wxy",-1)])]),_:1})]),i("p",null,[n[15]||(n[15]=o("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[13]||(n[13]=[o("LCTT",-1)])]),_:1}),n[16]||(n[16]=o(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:s(()=>[...n[14]||(n[14]=[o("Linux中國",-1)])]),_:1}),n[17]||(n[17]=o(" 榮譽推出",-1))])])}const P=d(a,[["render",x]]);export{w as __pageData,P as default};
